package com.archos.mediacenter.video.leanback.settings;

import android.app.Application;
import android.view.*;
import androidx.preference.PreferenceManager;
import com.archos.mediacenter.video.CustomApplication;
import com.archos.mediacenter.video.leanback.*;
import com.archos.mediacenter.video.utils.backup.*;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28,qualifiers="w960dp-h540dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class ProductionBackupSettingsTest {
    @Before public void setup(){ReflectionHelpers.setStaticField(PreviewSettings.class,"sidebarTrace",(java.util.function.Consumer<String>)value->System.out.println("SIDEBAR_TRACE "+value));PreviewAsyncFixtures.offlineTransport();ReflectionHelpers.setStaticField(CustomApplication.class,"systemLocale",java.util.Locale.getDefault());com.archos.environment.ArchosUtils.setGlobalContext(RuntimeEnvironment.getApplication());ReflectionHelpers.setStaticField(CustomApplication.class,"log",org.slf4j.LoggerFactory.getLogger(CustomApplication.class));ReflectionHelpers.setStaticField(CustomApplication.class,"mContext",RuntimeEnvironment.getApplication());PreferenceManager.getDefaultSharedPreferences(RuntimeEnvironment.getApplication()).edit().clear().putBoolean("try_new_ui",true).commit();try{com.squareup.picasso.Picasso.get();}catch(IllegalStateException missing){com.squareup.picasso.Picasso.setSingletonInstance(new com.squareup.picasso.Picasso.Builder(RuntimeEnvironment.getApplication()).build());}}
    private void layout(View root){root.measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));root.layout(0,0,960,540);}
    private View find(View root,String label){if(root instanceof android.widget.TextView&&label.contentEquals(((android.widget.TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),label);if(found!=null)return found;}return null;}
    @After public void drain()throws Exception{ReflectionHelpers.setStaticField(PreviewSettings.class,"sidebarTrace",null);PreviewAsyncFixtures.drain();}
    private VideoSettingsFragment.PrefsFragment install(TopNavigationTest.Host host){var fragment=new VideoSettingsFragment.PrefsFragment();host.getSupportFragmentManager().beginTransaction().replace(android.R.id.content,fragment).commitNow();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();layout(fragment.requireView());assertTrue(PreviewSettings.enterBackup(fragment));layout(fragment.requireView());return fragment;}
    private void capture(View root,String name)throws Exception{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(root.getWidth(),root.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);root.getViewTreeObserver().dispatchOnPreDraw();Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(500));root.draw(new android.graphics.Canvas(bitmap));java.io.File folder=new java.io.File("build/reports/preview-ui");folder.mkdirs();try(var output=new java.io.FileOutputStream(new java.io.File(folder,name+".png"))){assertTrue(bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output));}}
    private void assertBackupOpenerVisible(View root){View child=root.findViewWithTag("semantic:settings:section:preview_backup_restore");assertNotNull(child);android.graphics.Rect visible=new android.graphics.Rect();ViewParent parent=child.getParent();while(parent instanceof View&&!(parent instanceof android.widget.ScrollView))parent=parent.getParent();android.widget.ScrollView scroll=(android.widget.ScrollView)parent;android.graphics.Rect target=new android.graphics.Rect(0,0,child.getWidth(),child.getHeight());((ViewGroup)scroll.getChildAt(0)).offsetDescendantRectToMyCoords(child,target);String metrics="visible="+visible+", target="+target+", scrollY="+scroll.getScrollY()+", scrollHeight="+scroll.getHeight()+", padding="+scroll.getPaddingTop()+"/"+scroll.getPaddingBottom()+", contentHeight="+scroll.getChildAt(0).getHeight()+", childTop="+child.getTop()+", translationY="+child.getTranslationY()+", attached="+child.isAttachedToWindow();assertTrue(metrics,child.getGlobalVisibleRect(visible));assertEquals(metrics+", finalVisible="+visible+" of height "+child.getHeight(),child.getHeight(),visible.height());}
    private void await(BackupOperationModel model,BackupOperationModel.Phase expected)throws Exception{long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(15);while(model.isBusy()){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();if(System.nanoTime()>deadline)throw new AssertionError("Backup worker did not finish");Thread.sleep(10);}Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(model.current().message,expected,model.current().phase);}
    @Test public void recreatedSettingsKeepsFlatDetailsAndMeasuredPermanentSidebar()throws Throwable{
        var host=Robolectric.buildActivity(TopNavigationTest.Host.class).setup().visible();Throwable failure=null;try{var fragment=install(host.get());View root=fragment.requireView(),frame=root.findViewWithTag("settings.backup.workspace");int rail=((ViewGroup)frame.getParent()).getChildAt(0).getWidth();assertTrue(rail>0);capture(root,"0139-production-backup-main");assertBackupOpenerVisible(root);root.findViewWithTag("backup.details").performClick();layout(root);host.recreate();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();fragment=(VideoSettingsFragment.PrefsFragment)host.get().getSupportFragmentManager().findFragmentById(android.R.id.content);root=fragment.requireView();layout(root);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();layout(root);frame=root.findViewWithTag("settings.backup.workspace");assertEquals(View.VISIBLE,frame.getVisibility());assertEquals(rail,((ViewGroup)frame.getParent()).getChildAt(0).getWidth());assertNotNull(root.findViewWithTag("backup.details.page"));capture(root,"0139-production-backup-recreated-details");assertBackupOpenerVisible(root);BackupSettingsController controller=ReflectionHelpers.getField(fragment,"backupController");assertTrue(controller.back());layout(root);assertTrue(root.findViewWithTag("backup.details").hasFocus());assertTrue(controller.back());assertTrue(root.findViewWithTag("semantic:settings:section:preview_backup_restore").hasFocus());
        }catch(Throwable problem){failure=problem;throw problem;}finally{try{host.pause().stop().destroy();}catch(Throwable cleanup){if(failure!=null)failure.addSuppressed(cleanup);else throw cleanup;}}
    }
    @Test public void recreationKeepsPrivateReviewAndTemporaryCategoryOptOutUntilExplicitConfirmation()throws Throwable{
        var host=Robolectric.buildActivity(TopNavigationTest.Host.class).setup().visible();Throwable failure=null;try{var fragment=install(host.get());BackupOperationModel model=new androidx.lifecycle.ViewModelProvider(host.get()).get(BackupOperationModel.class);var prefs=PreferenceManager.getDefaultSharedPreferences(host.get());prefs.edit().putInt("preview_accent41",7).putString("oauth_token","AUTH_CANARY").commit();java.io.File source=new java.io.File(host.get().getCacheDir(),"review-source.zip");org.json.JSONObject appearance=new org.json.JSONObject().put("schema",1).put("category","APPEARANCE").put("values",new org.json.JSONObject().put("preview_accent41",new org.json.JSONObject().put("type","INT").put("value",19))),audio=new org.json.JSONObject().put("schema",1).put("category","AUDIO").put("values",new org.json.JSONObject());LogicalBackupArchive.writeCategories(source,Map.of(BackupCategory.APPEARANCE,appearance,BackupCategory.AUDIO,audio),()->false);model.open(new java.io.FileInputStream(source));await(model,BackupOperationModel.Phase.REVIEW);layout(fragment.requireView());var before=prefs.getAll();fragment.requireView().findViewWithTag("backup.category.AUDIO").performClick();assertEquals(before,prefs.getAll());host.recreate();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();fragment=(VideoSettingsFragment.PrefsFragment)host.get().getSupportFragmentManager().findFragmentById(android.R.id.content);layout(fragment.requireView());Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();layout(fragment.requireView());assertSame(model,new androidx.lifecycle.ViewModelProvider(host.get()).get(BackupOperationModel.class));BackupSettingsController controller=ReflectionHelpers.getField(fragment,"backupController");BackupWorkspace workspace=ReflectionHelpers.getField(controller,"workspace");assertEquals(Set.of(BackupCategory.APPEARANCE),workspace.selection());assertEquals(7,prefs.getInt("preview_accent41",0));fragment.requireView().findViewWithTag("backup.create").performClick();await(model,BackupOperationModel.Phase.RESTORE_PREVIEW);assertEquals(Set.of(BackupCategory.APPEARANCE),model.current().categories);assertEquals(7,prefs.getInt("preview_accent41",0));fragment.requireView().findViewWithTag("backup.operation:Restore selected categories").performClick();await(model,BackupOperationModel.Phase.RESTORED);assertEquals(19,prefs.getInt("preview_accent41",0));assertEquals("AUTH_CANARY",prefs.getString("oauth_token",null));assertTrue(source.exists());
        }catch(Throwable problem){failure=problem;throw problem;}finally{try{host.pause().stop().destroy();}catch(Throwable cleanup){if(failure!=null)failure.addSuppressed(cleanup);else throw cleanup;}}
    }
    @Test public void actualPreferencesFragmentBuildsFullSidebarAndAllBackupCategoriesAndFlatPages()throws Throwable{
        var host=Robolectric.buildActivity(TopNavigationTest.Host.class).setup().visible();Throwable failure=null;try{var fragment=new VideoSettingsFragment.PrefsFragment();host.get().getSupportFragmentManager().beginTransaction().replace(android.R.id.content,fragment).commitNow();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();View root=fragment.requireView();layout(root);View advanced=root.findViewWithTag("semantic:settings:category:Advanced");assertNotNull("Advanced sidebar",advanced);advanced.performClick();layout(root);View opener=find(root,"Backup & Restore");assertNotNull("Backup sidebar entry",opener);opener.performClick();layout(root);View frame=root.findViewWithTag("settings.backup.workspace");assertNotNull("Backup workspace",frame);assertEquals(View.VISIBLE,frame.getVisibility());for(BackupCategory category:BackupCategory.values()){View option=root.findViewWithTag("backup.category."+category.name());assertNotNull(category.name(),option);assertTrue(category.name(),option.getWidth()>0&&option.getHeight()>0);assertTrue(category.name(),option.getBottom()<=((View)option.getParent()).getHeight());}View details=root.findViewWithTag("backup.details");details.requestFocus();details.performClick();layout(root);assertNotNull(root.findViewWithTag("backup.details.page"));var controller=(BackupSettingsController)ReflectionHelpers.getField(fragment,"backupController");assertTrue(controller.back());layout(root);assertTrue(root.findViewWithTag("backup.details").hasFocus());assertTrue(controller.back());assertTrue(opener.hasFocus());
        }catch(Throwable problem){failure=problem;throw problem;}finally{try{host.pause().stop().destroy();}catch(Throwable cleanup){if(failure!=null)failure.addSuppressed(cleanup);else throw cleanup;}}
    }
}
